package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.*;import in.kabadiwala.connect.dto.AuthDtos.*;import in.kabadiwala.connect.service.AuthService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/v1/auth") public class AuthController {private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/otp/send") ApiResponse<?> send(@Valid @RequestBody OtpRequest r){String dev=s.sendOtp(r);Map<String,Object>d=new HashMap<>();if(dev!=null)d.put("developmentOtp",dev);return ApiResponse.ok("OTP sent",d);}@PostMapping("/otp/verify") ApiResponse<?> verify(@Valid @RequestBody OtpVerify r){s.verifyOtp(r);return ApiResponse.ok("OTP verified",null);}@PostMapping("/register") ApiResponse<?> register(@Valid @RequestBody Register r){return ApiResponse.ok("Registered",s.register(r));}@PostMapping("/login") ApiResponse<?> login(@Valid @RequestBody Login r){return ApiResponse.ok("Logged in",s.login(r));}@PostMapping("/refresh") ApiResponse<?> refresh(@RequestBody Refresh r){return ApiResponse.ok("Token refreshed",s.refresh(r.refreshToken()));}@PostMapping("/logout") ApiResponse<?> logout(Authentication a,@RequestBody Refresh r){s.logout(a.getName(),r.refreshToken());return ApiResponse.ok("Logged out",null);}@PostMapping("/forgot-password") ApiResponse<?> reset(@RequestBody Map<String,String> r){s.resetPassword(r.get("mobile"),r.get("otp"),r.get("newPassword"));return ApiResponse.ok("Password updated",null);}}
